"use client";

/* eslint-disable @next/next/no-img-element -- qrUrl is generated by the backend and must be rendered directly. */

import Link from "next/link";
import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { ArrowLeft, CheckCircle2, Clock3, Copy, QrCode } from "lucide-react";
import { toast } from "sonner";
import { PageHeader } from "@/components/page-header";
import { StatusBadge } from "@/components/status-badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  usePaymentOrder,
  usePaymentOrderQr,
} from "@/features/payment-orders/hooks";
import { ManualCashForm } from "@/features/payment-transactions/components/manual-cash-form";
import { formatCurrency, formatDate } from "@/lib/format";
import { can, PERMISSIONS } from "@/lib/permissions";
import { useAuthStore } from "@/stores/auth-store";

export default function PaymentOrderPage() {
  const id = String(useParams<{ id: string }>().id);
  const order = usePaymentOrder(id);
  const qr = usePaymentOrderQr(id);
  const role = useAuthStore((state) => state.user?.role);
  const [remaining, setRemaining] = useState(0);
  useEffect(() => {
    const update = () =>
      setRemaining(
        qr.data?.expiresAt
          ? Math.max(0, new Date(qr.data.expiresAt).getTime() - Date.now())
          : 0,
      );
    update();
    const timer = window.setInterval(update, 1000);
    return () => window.clearInterval(timer);
  }, [qr.data?.expiresAt]);
  if (order.isLoading) return <Skeleton className="h-[600px] w-full" />;
  if (!order.data)
    return <p className="text-rose-600">Không tìm thấy yêu cầu thanh toán.</p>;
  const data = order.data;
  const minutes = Math.floor(remaining / 60_000);
  const seconds = Math.floor((remaining % 60_000) / 1_000);
  const copy = (value: string) =>
    navigator.clipboard
      .writeText(value)
      .then(() => toast.success("Đã sao chép"));
  return (
    <>
      <PageHeader
        eyebrow="Yêu cầu thanh toán"
        title={data.orderCode}
        description={`${data.student?.fullName ?? "Học sinh"} · Tạo lúc ${formatDate(data.createdAt, true)}`}
        actions={
          <Button variant="outline" asChild>
            <Link href={`/students/${data.studentId}`}>
              <ArrowLeft />
              Hồ sơ học sinh
            </Link>
          </Button>
        }
      />
      {data.status === "PAID" && (
        <div className="mb-5 flex items-center gap-3 rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-emerald-800">
          <CheckCircle2 className="size-6" />
          <div>
            <p className="font-bold">Thanh toán thành công</p>
            <p className="text-sm text-emerald-700">
              Công nợ và phiếu thu đã được cập nhật tự động.
            </p>
          </div>
        </div>
      )}
      <div className="grid gap-5 xl:grid-cols-[0.9fr_1.1fr]">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <QrCode className="size-5 text-teal-700" />
              Mã QR thanh toán
            </CardTitle>
          </CardHeader>
          <CardContent>
            {data.paymentMethod === "CASH" ? (
              <div className="flex min-h-80 flex-col items-center justify-center rounded-2xl bg-amber-50 text-center">
                <span className="mb-3 flex size-16 items-center justify-center rounded-full bg-white text-3xl">
                  ₫
                </span>
                <p className="font-display text-xl font-bold text-amber-900">
                  Thu tiền mặt tại quầy
                </p>
                <p className="mt-2 max-w-xs text-sm text-amber-700">
                  Thu quỹ ghi nhận giao dịch bằng biểu mẫu bên dưới.
                </p>
              </div>
            ) : qr.data?.qrUrl ? (
              <div className="flex flex-col items-center">
                <img
                  src={qr.data.qrUrl}
                  alt={`QR thanh toán ${data.orderCode}`}
                  className="aspect-square w-full max-w-[330px] rounded-2xl border border-slate-100 object-contain p-3"
                />
                <p className="mt-3 text-xs text-slate-400">
                  Quét bằng ứng dụng ngân hàng
                </p>
              </div>
            ) : (
              <div className="flex min-h-80 items-center justify-center rounded-2xl bg-slate-50 text-sm text-slate-500">
                Không có mã QR. Kiểm tra cấu hình ngân hàng của trường.
              </div>
            )}
          </CardContent>
        </Card>
        <div className="space-y-5">
          <Card>
            <CardContent className="pt-5">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-xs font-bold uppercase tracking-wider text-slate-400">
                    Số tiền thanh toán
                  </p>
                  <p className="mt-2 font-display text-4xl font-bold text-slate-950">
                    {formatCurrency(data.requestedAmount)}
                  </p>
                </div>
                <StatusBadge status={qr.data?.status ?? data.status} />
              </div>
              <div className="mt-5 grid gap-3 rounded-xl bg-slate-50 p-4 sm:grid-cols-2">
                <Info label="Ngân hàng" value={data.bankCode || "—"} />
                <Info
                  label="Số tài khoản"
                  value={data.bankAccountNumber || "—"}
                  copy={() =>
                    data.bankAccountNumber && copy(data.bankAccountNumber)
                  }
                />
                <Info
                  label="Nội dung chuyển tiền"
                  value={data.transferContent}
                  copy={() => copy(data.transferContent)}
                />
                <Info
                  label="Còn hiệu lực"
                  value={
                    remaining > 0
                      ? `${minutes}:${String(seconds).padStart(2, "0")}`
                      : "Đã hết hạn"
                  }
                  icon={<Clock3 className="size-4" />}
                />
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle>Chi tiết phân bổ</CardTitle>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Khoản công nợ</TableHead>
                    <TableHead className="text-right">Số tiền</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.items.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <p className="font-medium text-slate-900">
                          {item.receivable?.description ??
                            item.receivable?.receivableCode ??
                            item.receivableId}
                        </p>
                        <p className="font-mono text-xs text-slate-400">
                          {item.receivable?.receivableCode}
                        </p>
                      </TableCell>
                      <TableCell className="text-right font-semibold">
                        {formatCurrency(item.requestedAmount)}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </div>
      </div>
      {data.paymentMethod === "CASH" &&
        data.status === "PENDING" &&
        can(role, PERMISSIONS.collect) && (
          <div className="mt-5">
            <ManualCashForm
              orderId={id}
              orderCode={data.orderCode}
              amount={data.requestedAmount}
            />
          </div>
        )}
    </>
  );
}

function Info({
  label,
  value,
  copy,
  icon,
}: {
  label: string;
  value: string;
  copy?: () => void;
  icon?: React.ReactNode;
}) {
  return (
    <div>
      <p className="text-[11px] font-bold uppercase tracking-wider text-slate-400">
        {label}
      </p>
      <div className="mt-1.5 flex items-center gap-2 text-sm font-bold text-slate-800">
        {icon}
        {value}
        {copy && (
          <button
            onClick={copy}
            className="rounded p-1 text-slate-400 hover:text-teal-700"
          >
            <Copy className="size-3.5" />
          </button>
        )}
      </div>
    </div>
  );
}
